import io
import os
import sys

repositoryRoot = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                               '..', '..'))
if os.path.join(repositoryRoot, 'definitions') not in sys.path:
    sys.path.insert(0, os.path.join(repositoryRoot, 'definitions'))

from enumTypes import enumTypes

headerPath = os.path.join(repositoryRoot, 'src', 'Autogenerated', 'EnumTypes.h')


#%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
def CheckTable():
    """unique names, unique integer values per enum; returns nothing, raises on error"""
    pythonNames = set()
    for enum in enumTypes:
        if enum.pythonName in pythonNames:
            raise ValueError('enumTypes: duplicate enum ' + enum.pythonName)
        pythonNames.add(enum.pythonName)
        names, values = set(), set()
        for value in enum.values:
            if value.name in names:
                raise ValueError('enumTypes: ' + enum.pythonName + '.' + value.name + ' declared twice')
            names.add(value.name)
            if isinstance(value.value, int):
                if value.value in values:
                    raise ValueError('enumTypes: ' + enum.pythonName + '.' + value.name + ' reuses value ' + str(value.value))
                values.add(value.value)
            if enum.bits and isinstance(value.value, int) and not 0 <= value.value < 31:
                raise ValueError('enumTypes: ' + enum.pythonName + '.' + value.name + ': bit out of range')


def ValueString(enum, value):
    if value.value is None:
        return '0'
    if isinstance(value.value, str):
        return value.value
    if enum.bits:
        return '1 << ' + str(value.value)
    return str(value.value)


def Aligned(text, width):
    return text + ' ' * max(1, width - len(text))


def EnumText(enum, indent):
    s = ''
    if enum.cppNote != '':
        s += indent + '//! ' + enum.cppNote + '\n'
    if enum.Namespace() == '':
        s += indent + 'enum class ' + enum.EnumName() + ' {\n'
    else:
        s += indent + 'enum ' + enum.EnumName() + ' {\n'
    width = max(len(v.name) + len(ValueString(enum, v)) for v in enum.values) + 5
    for index, value in enumerate(enum.values):
        separator = '' if index + 1 == len(enum.values) else ','
        s += (indent + '    ' + Aligned(value.name + ' = ' + ValueString(enum, value) + separator, width)
              + '//!< ' + value.description + '\n')
    s += indent + '};\n'
    return s


def StringFunctionText(enum, indent):
    if enum.stringFunction is None:
        return ''
    name = enum.EnumName()
    scope = enum.Namespace() + '::' if enum.Namespace() != '' else name + '::'
    s = '\n'
    if enum.stringFunction == 'operator<<':
        s += indent + '//! ostream operator for printing of ' + name + '\n'
        s += indent + 'inline std::ostream& operator<<(std::ostream& os, ' + name + ' value)\n'
        s += indent + '{\n'
        s += indent + '    switch (value)\n'
        s += indent + '    {\n'
        for value in enum.values:
            s += indent + '    case ' + scope + value.name + ': return os << "' + value.name[len(enum.stringPrefix):] + '";\n'
        s += indent + '    default: return os << "' + name + '::invalid";\n'
        s += indent + '    }\n'
        s += indent + '}\n'
        return s

    function = enum.stringFunction
    errorText = '"' + enum.Namespace() + '::' + function + '(...) called for invalid type!"'
    s += indent + '//! transform type into string (e.g. for error messages); this is slow and cannot be used during computation!\n'
    s += indent + 'inline STDstring ' + function + '(' + name + ' var)\n'
    s += indent + '{\n'
    if enum.bits:
        s += indent + '    STDstring t; //empty string\n'
        for value in enum.values:
            if value.value is None:
                s += indent + '    if (var == ' + value.name + ') { t = "_None/Undefined"; }\n'
            elif value.stringText != '':
                text = value.stringText if value.stringText is not None else value.name[len(enum.stringPrefix):]
                condition = 'var & ' + value.name
                if value.stringIf:
                    condition = '(' + condition + ') && ' + value.stringIf
                s += indent + '    if (' + condition + ') { t += "' + text + '"; }\n'
        s += indent + '    if (t.length() == 0) { CHECKandTHROWstring(' + errorText + '); }\n'
        s += indent + '    return t;\n'
    else:
        s += indent + '    switch (var)\n'
        s += indent + '    {\n'
        for value in enum.values:
            text = '_None/Undefined' if value.name == '_None' else value.name[len(enum.stringPrefix):]
            s += indent + '    case ' + value.name + ': return "' + text + '";\n'
        s += indent + '    default: CHECKandTHROWstring(' + errorText + '); return "";\n'
        s += indent + '    }\n'
    s += indent + '}\n'
    return s


#%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
def EmitHeader():
    """write EnumTypes.h if its content changed; returns True if written"""
    CheckTable()
    s = ''
    s += '/** ' + '*' * 92 + '\n'
    s += '* @brief        AUTO GENERATED FILE - DO NOT EDIT\n'
    s += '*\n'
    s += '* @details      The enumeration types shared by C++ and Python, and their string functions,\n'
    s += '*               generated from definitions/enumTypes.py by tools/generators/enumEmitter.py.\n'
    s += '*               Namespaces (Node, Joint, Contact) are reopened by the hand-written headers\n'
    s += '*               for their further helper functions.\n'
    s += '*\n'
    s += '* @author       Gerstmayr Johannes\n'
    s += '* @copyright    This file is part of Exudyn. Exudyn is free software: see LICENSE.txt\n'
    s += '*\n'
    s += '************************************************************************************* */\n'
    s += '\n'
    s += '#ifndef ENUMTYPES__H\n'
    s += '#define ENUMTYPES__H\n'
    s += '\n'
    s += '#include <ostream>\n'
    s += '#include "Utilities/ReleaseAssert.h"\n'
    s += '#include "Utilities/BasicDefinitions.h"\n'

    namespaces = []
    for enum in enumTypes:
        if enum.Namespace() not in namespaces:
            namespaces.append(enum.Namespace())
    #namespaced enums first: enum classes may refer to their values (AccessFunctionType = Marker::...)
    namespaces = [n for n in namespaces if n != ''] + ([''] if '' in namespaces else [])
    for namespace in namespaces:
        members = [e for e in enumTypes if e.Namespace() == namespace]
        if namespace == '':
            for enum in members:
                s += '\n' + EnumText(enum, '') + StringFunctionText(enum, '')
        else:
            s += '\nnamespace ' + namespace + ' {\n'
            for index, enum in enumerate(members):
                s += ('\n' if index else '') + EnumText(enum, '    ') + StringFunctionText(enum, '    ')
            s += '} //namespace ' + namespace + '\n'
    s += '\n#endif //ENUMTYPES__H\n'

    existing = ''
    if os.path.exists(headerPath):
        existing = io.open(headerPath, encoding='utf8').read()
    if existing != s:
        io.open(headerPath, 'w', encoding='utf8', newline='\n').write(s)
    return existing != s


if __name__ == '__main__':
    print('EnumTypes.h written' if EmitHeader() else 'EnumTypes.h unchanged')
